/* ==========================================================================
   dict.js — 영어 단어 사전 (3~8글자)
   --------------------------------------------------------------------------
   출처: ENABLE word list (public domain) ∩ 뜻을 확보한 단어

   필터
     · 순수 소문자 알파벳 단어만  → 고유명사·약어·숫자 섞인 문자열 제외
     · 3글자 미만 제외        → 두 글자가 단어로 굳으면 긴 단어를 못 만든다
     · 뜻이 확인된 단어만 채택    → 만든 단어는 반드시 더블클릭으로 뜻을 볼 수 있다

   길이별로 구분자 없이 이어붙인 고정폭 문자열. 로드 시 Set 으로 펼친다.
   여기 있는 단어는 전부 만들 수 있고, 재화를 번다.
   그중 30개(data.js 의 G.WORDS)만 특별한 능력을 가진다.
   총 65014개
   ========================================================================== */
var G = window.G || (window.G = {});

G.MIN_WORD_LEN = 3;
G.MAX_WORD_LEN = 8;

G.DICT_RAW = {
  3: "",
  4: "",
  5: "",
  6: "",
  7: "",
  8: ""
};

G.DICT = (function () {
  var set = Object.create(null), n, s, i, L;
  for (n in G.DICT_RAW) {
    L = +n; s = G.DICT_RAW[n];
    for (i = 0; i < s.length; i += L) set[s.substr(i, L)] = 1;
  }
  G.DICT_RAW = null;
  return set;
})();

/** 이 글자열이 만들 수 있는 단어인가 */
G.isWord = function (t) { return G.DICT[t] === 1; };
